/**
 * Remark plugin: rewrites local markdown image refs to the optimized WebP
 * generated by scripts/optimize-images.mjs, and injects width/height to
 * prevent layout shift.
 *
 * Reads public/.imgmap.json (created at build time by the optimize script).
 */
import { visit } from 'unist-util-visit';
import { readFileSync, existsSync } from 'node:fs';

const EXTS = /\.(png|jpe?g)(\?.*)?$/i;

export default function remarkOptimizeImages() {
  let imgmap = null;
  return (tree, file) => {
    if (!imgmap) {
      const p = new URL('../../public/.imgmap.json', import.meta.url);
      if (existsSync(p.pathname)) {
        try { imgmap = JSON.parse(readFileSync(p.pathname, 'utf8')); } catch { imgmap = {}; }
      } else {
        imgmap = {};
      }
    }

    visit(tree, 'image', (node) => {
      if (!node.url || node.url.startsWith('http') || node.url.startsWith('data:')) return;
      if (!EXTS.test(node.url)) return;
      const clean = node.url.split('?')[0];
      const entry = imgmap[clean];
      if (!entry) return;
      node.url = entry.webp;
      node.data = node.data || {};
      node.data.hProperties = node.data.hProperties || {};
      node.data.hProperties.width = entry.width;
      node.data.hProperties.height = entry.height;
      node.data.hProperties.loading = 'lazy';
      node.data.hProperties.decoding = 'async';
    });
  };
}
